+#[test]
+fn a_child_on_the_parents_endpoint_gets_the_key_the_parent_used() {
+    let env = Env::new(
+        "delegate-key-fallback",
+        json!({ "steps": [delegate("hi"), { "text": "hello" }, { "text": "done" }] }),
+    );
+    env.config(&agent_config(&env, ""));
+    // The parent resolves OPENROUTER_API_KEY; the child must get that same key.
+    let out = env
+        .run_with(&[("OPENAI_API_KEY", ""), ("OPENROUTER_API_KEY", "openrouter-CCCC")], &["run", "--no-learn", "go"]);
+    assert!(out.status.success(), "{}", text(&out));
+    assert_eq!(env.requests().len(), 3, "{}", text(&out));
+    // Parent, child, parent: all three requests carry the fallback key.
+    assert_eq!(
+        auth_seen(&env),
+        vec![json!("Bearer open…"), json!("Bearer open…"), json!("Bearer open…")],
+        "{}",
+        text(&out)
+    );
+}
+
+#[test]
+fn with_no_key_the_run_fails_before_any_request() {
+    let env = Env::new("delegate-no-key", json!({ "steps": [delegate("hi"), { "text": "hello" }] }));
+    env.config(&agent_config(&env, ""));
+    let out = env.run_with(&[("OPENAI_API_KEY", ""), ("OPENROUTER_API_KEY", "")], &["run", "--no-learn", "go"]);
+    assert!(!out.status.success(), "{}", text(&out));
+    assert!(text(&out).contains("no API key: set OPENAI_API_KEY or OPENROUTER_API_KEY"), "{}", text(&out));
+    assert!(env.requests().is_empty(), "a request was sent without a key");
+    assert!(env.journal().is_empty(), "the session started without a key");
+}
+
+/// An explicitly keyless endpoint (`api_key_secret = ""`) still builds and runs
+/// without auth, so the no-key check must not reject it.
+#[test]
+fn an_explicitly_keyless_endpoint_still_works() {
+    let env =
+        Env::new("delegate-keyless", json!({ "steps": [delegate("hi"), { "text": "hello" }, { "text": "done" }] }));
+    env.config(&format!("api_key_secret = \"\"\n{}", agent_config(&env, "")));
+    let out = env.run_with(&[("OPENAI_API_KEY", "")], &["run", "--no-learn", "go"]);
+    assert!(out.status.success(), "{}", text(&out));
+    assert_eq!(env.requests().len(), 3, "{}", text(&out));
+    assert!(auth_seen(&env).iter().all(Value::is_null), "{:?}", auth_seen(&env));
+}
